import{_ as e,o as t,c as i,a5 as o}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"共同操作の権限と認証","description":"","frontmatter":{"title":"共同操作の権限と認証","docId":"developer.collaboration","translationKey":"developer.collaboration","locale":"ja","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"fb71673a581e923e3c02ae401a46937b007f9919690ca020d22c27b370b6c61d","translationRevision":"865986ab5e4decd6af3e5c1323996ca481fc22ab17bfcd378ca46ab7d8469b72","order":190},"headers":[],"relativePath":"ja/developer/collaboration.md","filePath":"ja/developer/collaboration.md","lastUpdated":1794611623000}'),s={name:"ja/developer/collaboration.md"};function r(l,a,n,d,h,c){return t(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="collaboration-authority-and-authentication" tabindex="-1">共同操作の権限と認証 <a class="header-anchor" href="#collaboration-authority-and-authentication" aria-label="Permalink to &quot;共同操作の権限と認証 {#collaboration-authority-and-authentication}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>承認済み端末が既存ホストで範囲を絞った操作を調査・実行できるようにします。テスト用所有者プロファイル、リモート対応ビルド、設定済み通信を使います。アカウントログイン、Cloud チーム所属、ローカル所有権、直接委任セッションは異なる権限です。</p><h2 id="establish-the-trust-chain" tabindex="-1">信頼の連鎖を確立する <a class="header-anchor" href="#establish-the-trust-chain" aria-label="Permalink to &quot;信頼の連鎖を確立する {#establish-the-trust-chain}&quot;">​</a></h2><p>ローカル所有者用の <code>collaboration.*</code> 管理が設定、招待、保留要求、主体、権限付与、セッション、監査を所有します。リスナー設定や認証情報作成の前にスキーマを検出します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.configure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.invites.create</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>招待はペアリングを始めるもので、それ自体では業務上の権限を与えません。所有者の承認で対応するセッションと権限が作られます。直接 HTTPS では検証済み証明書か明示的に固定したネイティブ信頼が必要です。ネイティブ Bearer とブラウザー Cookie の境界は異なります。最初の <code>collaboration.hello</code> がプロトコル、ホストインスタンス、主体、セッション、権限リビジョン、機能、交渉済み上限を結び付けます。</p><h2 id="authorize-each-operation" tabindex="-1">操作ごとに認可する <a class="header-anchor" href="#authorize-each-operation" aria-label="Permalink to &quot;操作ごとに認可する {#authorize-each-operation}&quot;">​</a></h2><p>対応リモートメソッドは許可リスト、機能、リソース制限、現在のセッション検査を通過する必要があります。ワークフローの無効化・削除は永続的な compare-and-set メタデータを使います。ポイント調整は加算型で独自の付与制限があります。リモート自動化の読み取りは限定された要約です。無効な作成者所有の下書きを保存しても、所有者の実行権限は得られません。</p><p>所有者の確認・採用と検査付き承認は、現在の定義、依存関係、出所を結び付けます。プレビューマニフェストは調査情報で、実行トークンではありません。通信相手の ID を恒久権限と扱わず、実行境界で付与とリソースの結び付きを再検証します。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>直接ネイティブ共同操作には範囲付き読み取り、一部の永続的変更、制限付き復旧が実装されています。Cloud teams/relay は別のアダプターを持ちます。文書化された Cloud リレー読み取りを完全な管理や下書き実行と説明してはいけません。残る委任処理、ドメイン書き込み、複数 PC の受け入れは実験段階です。経路に応じて<a href="./remote-client.html">リモートクライアント</a> と <a href="./cloud.html">Cloud</a> を参照します。</p><h2 id="recover-and-verify" tabindex="-1">復旧と検証 <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to &quot;復旧と検証 {#recover-and-verify}&quot;">​</a></h2><p>取り消しや本人情報の変更では購読を停止し、非公開の投影を破棄します。交渉済みドメインとカーソルの有効性に従って <code>collaboration.subscribe</code>、<code>snapshot</code>、<code>resume</code> を使います。応答が不確実なら元のコマンド ID を解決します。新しい ID で削除を再試行したり、古い受領記録から権限を復元したりしません。<a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-collaboration/src" target="_blank" rel="noreferrer">認可ソース</a> とレジストリ方針が境界を定めます。TLS 成功だけでは認可テストになりません。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>Teams は端末登録、招待・アクセス要求、承認、ホストによる現在のネイティブ権限版の確認の順です。<code>pendingHost</code> は最後が未完了です。新しい版は以前の確認を無効にし、古い expectedRevision では再読します。ネイティブ受入には新しい snapshot・稼働 host/端末・有効権限・confirmedRevision と revision の一致が必要です。UI は host/参加・利用可能承認を出しますが、ネイティブ確認は API 契約で全 build にボタンを約束しません。</p><p>旧 role の変換は閉じた集合です。observer は live/workflow/points/competition/automation/outcome 読み取り、moderator はポイント調整・workflow/automation toggle・競技管理を追加、automationEditor は読み取りに編集を追加します。どの preset も任意 script・外部効果・再利用委任を暗黙付与しません。明示 <code>nativeGrant</code> は <code>custom</code> が必要でリソース・効果範囲・delta を限定します。種別は <code>desktop</code>・<code>agent</code> のみ。不対応 policy は拡権せず失敗します。pairing・host 確認・版・伝送を分けて診断します。</p>`,17)])])}const u=e(s,[["render",r]]);export{k as __pageData,u as default};
